def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]

    # Locate the connected, two-column color legend in the lower-left.
    remaining = {
        (r, c) for r in range(h) for c in range(w) if grid[r][c] != bg
    }
    legends = []
    while remaining:
        start = remaining.pop()
        cells = {start}
        stack = [start]
        while stack:
            r, c = stack.pop()
            for p in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
                if p in remaining:
                    remaining.remove(p)
                    cells.add(p)
                    stack.append(p)
        colors = {grid[r][c] for r, c in cells}
        rs = [r for r, c in cells]
        cs = [c for r, c in cells]
        if (len(colors) > 1 and max(cs) - min(cs) == 1
                and min(rs) >= h // 2 and min(cs) <= w // 3):
            legends.append(cells)

    if not legends:
        return [row[:] for row in grid]

    legend = max(legends, key=len)
    top = min(r for r, c in legend)
    bottom = max(r for r, c in legend)
    left = min(c for r, c in legend)

    mappings = []
    for r in range(top, bottom + 1):
        if (r, left) in legend:
            mappings.append((grid[r][left], grid[r][left + 1]))

    # Gather same-color components outside the legend.
    remaining = {
        (r, c) for r in range(h) for c in range(w)
        if grid[r][c] != bg and (r, c) not in legend
    }
    by_color = {}
    while remaining:
        start = remaining.pop()
        color = grid[start[0]][start[1]]
        cells = {start}
        stack = [start]
        while stack:
            r, c = stack.pop()
            for p in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
                if p in remaining and grid[p[0]][p[1]] == color:
                    remaining.remove(p)
                    cells.add(p)
                    stack.append(p)
        by_color.setdefault(color, []).append(cells)

    rectangles = {}
    paired_cells = set()

    # Opposite L triominoes of one color mark a rectangle.
    for color, components in by_color.items():
        ls = []
        for cells in components:
            if len(cells) != 3:
                continue
            rs = [r for r, c in cells]
            cs = [c for r, c in cells]
            if max(rs) - min(rs) != 1 or max(cs) - min(cs) != 1:
                continue
            corners = {
                (min(rs), min(cs)), (min(rs), max(cs)),
                (max(rs), min(cs)), (max(rs), max(cs))
            }
            missing = list(corners - cells)
            if len(missing) == 1:
                m = missing[0]
                orient = (m[0] == max(rs), m[1] == max(cs))
                ls.append((cells, orient))

        used = set()
        for i, (a, oa) in enumerate(ls):
            if i in used:
                continue
            for j in range(i + 1, len(ls)):
                if j in used:
                    continue
                b, ob = ls[j]
                if oa[0] != ob[0] and oa[1] != ob[1]:
                    anchors = a | b
                    rectangles.setdefault(color, []).append(anchors)
                    paired_cells.update(anchors)
                    used.update((i, j))
                    break

    out = [row[:] for row in grid]

    # Legend rows specify source-to-fill colors. Later rows are layered first,
    # so earlier rows can draw over them.
    for source, target in reversed(mappings):
        for anchors in rectangles.get(source, []):
            r0 = min(r for r, c in anchors)
            r1 = max(r for r, c in anchors)
            c0 = min(c for r, c in anchors)
            c1 = max(c for r, c in anchors)
            for r in range(r0, r1 + 1):
                for c in range(c0, c1 + 1):
                    out[r][c] = target
            for r, c in anchors:
                out[r][c] = source

        # Components not used as paired L markers are recolored directly.
        for cells in by_color.get(source, []):
            if not (cells & paired_cells):
                for r, c in cells:
                    out[r][c] = target

    return out
